const mossDetailedCaption = (spec) => {
    const [, subject, scene, composition, lighting, palette, style, details, exclusions] = spec;
    return `创作一张${style}的完整画面。主体是${subject}。场景设定在${scene}。构图采用${composition}。光线设计为${lighting}。整体配色以${palette}为主，保持色彩层级稳定、材质颜色可信。\n\n画面必须具体呈现：${details}。主体数量、身份、动作、物体关系和空间透视必须准确；所有可见结构都符合真实用途与重力，边缘清楚，局部细节丰富但不堆砌。\n\n排除要求：${exclusions}。保持主题集中、构图完整、视觉风格统一，不添加未要求的品牌、装饰、边框或额外文字。`;
};
const mossLayoutBox = (height, width, top, left, bottom, right) => [
    Math.round(height * top), Math.round(width * left), Math.round(height * bottom), Math.round(width * right),
];
const mossDetailedLayout = (preset, spec, width = 1536, height = 1024) => {
    const [, subject, style, title, subtitle, body, palette, composition] = spec;
    return JSON.stringify({
        summary: { meta: [preset.label, style], canvas: "single", caption: `${preset.label}画面，主体为${subject}。采用${style}，配色为${palette}。${composition}。文字必须按给定原文清晰呈现，产品或对象结构真实，信息层级明确，避免无关装饰与重复元素。` },
        items: [
            { label: "text", caption: `画面顶部的主标题，使用与${style}一致的高识别度字形，字号最大、边缘清晰并保留充足留白。`, text: title, bbox: mossLayoutBox(height, width, -.445, -.448, -.318, .448) },
            { label: "text", caption: `主标题下方的副标题，字重低于主标题，与背景保持高对比并准确保留标点。`, text: subtitle, bbox: mossLayoutBox(height, width, -.303, -.406, -.219, .406) },
            { label: "object", caption: `${subject}。完整呈现关键外观、结构、材质、比例与空间关系；采用符合${style}的精细表现，主体不可被文字遮挡或裁切。`, bbox: mossLayoutBox(height, width, -.191, -.438, .262, .104) },
            { label: "text", caption: `右下信息区，按原有换行清晰排版，数字、中文、英文和符号均需准确，行距舒适。`, text: body, bbox: mossLayoutBox(height, width, -.113, .135, .389, .448) },
        ],
        bbox_coord_space: "abs_centralized",
        bbox_format: "yxyx",
    }, null, 2);
};
const mossScaleLegacyLayout = (prompt, width, height) => {
    try {
        const layout = JSON.parse(prompt);
        if (layout?.bbox_coord_space !== "abs_centralized" || layout?.bbox_format !== "yxyx" || !Array.isArray(layout.items)) return prompt;
        layout.items = layout.items.map((item) => ({ ...item, bbox: Array.isArray(item.bbox) && item.bbox.length === 4 ? [
            Math.round(item.bbox[0] * height / 1024), Math.round(item.bbox[1] * width / 1536),
            Math.round(item.bbox[2] * height / 1024), Math.round(item.bbox[3] * width / 1536),
        ] : item.bbox }));
        return JSON.stringify(layout, null, 2);
    } catch { return prompt; }
};
const mossPresetDemo = (image, width = 1536, height = 1024) => {
    const legacyStyle = MOSS_LEGACY_PRESET_STYLES[image.mossPreset];
    if (legacyStyle) {
        const prompt = (MOSS_TEMPLATES[legacyStyle] || MOSS_TEMPLATES.general)[1];
        return MOSS_LAYOUT_GUIDE_STYLES.has(legacyStyle) ? mossScaleLegacyLayout(prompt, width, height) : prompt;
    }
    const preset = MOSS_PRESET_BY_ID.get(image.mossPreset) || MOSS_PRESET_BY_ID.get("general_free");
    const spec = MOSS_DEMO_SPECS[preset.id] || MOSS_DEMO_SPECS.general_free;
    return spec[0] === "layout" ? mossDetailedLayout(preset, spec, width, height) : mossDetailedCaption(spec);
};
