const normalizeState = (raw, projectName) => {
    let state = {};
    try { state = JSON.parse(String(raw || "{}")); } catch {}
    const shots = Array.isArray(state.shots) && state.shots.length ? state.shots : [{ id: makeId(), title: "分镜 1" }];
    const normalizeImage = (image, index, legacy = {}) => {
        let lastOutput = image?.lastOutput && typeof image.lastOutput === "object" ? { ...image.lastOutput } : legacy.lastOutput && typeof legacy.lastOutput === "object" ? { ...legacy.lastOutput } : null;
        const outputs = Array.isArray(image?.outputs) ? image.outputs.filter((item) => item && typeof item === "object").slice(-10).map((item) => ({ ...item })) : lastOutput ? [lastOutput] : [];
        lastOutput ||= outputs.at(-1) || null;
        return ({
        id: String(image?.id || makeId()),
        title: String(image?.title || `图片 ${String(index + 1).padStart(2, "0")}`),
        selected: image?.selected !== false,
        mode: "text",
        style: [...Object.keys(MOSS_TEMPLATES), "photo", "illustration", "typography"].includes(image?.style) ? image.style : "general",
        mossPreset: MOSS_PRESET_BY_ID.has(image?.mossPreset) ? image.mossPreset : (MOSS_PRESETS.find((item) => item.style === image?.style)?.id || "general_free"),
        qwenTextPreset: QWEN21_TEXT_PRESET_MAP.has(image?.qwenTextPreset) ? image.qwenTextPreset : "text_to_image",
        qwenTextOption: String(image?.qwenTextOption || ""),
        qwenEditPreset: QWEN21_EDIT_PRESET_MAP.has(image?.qwenEditPreset) ? image.qwenEditPreset : "free_edit",
        qwenEditOption: String(image?.qwenEditOption || ""),
        cameraPreset: String(image?.cameraPreset || ""),
        framingPreset: String(image?.framingPreset || "medium"),
        propPreset: String(image?.propPreset || "none"),
        lightPreset: String(image?.lightPreset || "softbox"),
        prompt: String(image?.prompt ?? legacy.prompt ?? ""),
        negative: String(image?.negative ?? legacy.negative ?? ""),
        referenceImages: Array.isArray(image?.referenceImages) ? image.referenceImages.filter((item) => item && typeof item === "object").map((item) => ({ ...item })) : [],
        editPreset: String(image?.editPreset || "free_edit"),
        drawCount: Math.max(1, Math.min(10, Math.round(Number(image?.drawCount || legacy.drawCount || 1)))),
        outputs,
        deletedOutputs: Array.isArray(image?.deletedOutputs) ? image.deletedOutputs.map(String).filter(Boolean).slice(-100) : [],
        lastPromptId: String(image?.lastPromptId || legacy.lastPromptId || ""),
        lastOutput,
    });
    };
    state = {
        version: 2,
        projectName: String(projectName || state.projectName || "MOSS图片素材工程"),
        modelProfile: "MOSS",
        kreaCategory: KREA_CATEGORIES.some((item) => item.id === state.kreaCategory) ? state.kreaCategory : "people",
        kreaPreset: KREA_CATEGORIES.flatMap((item) => item.items).some((item) => item.id === state.kreaPreset)
            ? state.kreaPreset
            : "realistic",
        generationMode: "文生图",
        globalDrawCount: Boolean(state.globalDrawCount),
        cleanupSettings: {
            cache: Boolean(state.cleanupSettings?.cache),
            vram: Boolean(state.cleanupSettings?.vram),
            models: Boolean(state.cleanupSettings?.models),
            every: Math.max(1, Math.min(99, Number(state.cleanupSettings?.every || 1))),
            monitorHardware: Boolean(state.cleanupSettings?.monitorHardware),
        },
        generationProgress: {
            title: String(state.generationProgress?.title || "等待生成"),
            percent: Math.max(0, Math.min(100, Number(state.generationProgress?.percent) || 0)),
            batchText: String(state.generationProgress?.batchText || ""),
            imageStartedAt: Math.max(0, Number(state.generationProgress?.imageStartedAt) || 0),
            imageElapsedMs: Math.max(0, Number(state.generationProgress?.imageElapsedMs) || 0),
        },
        width: snap32(state.width),
        height: snap32(state.height),
        aspect: RESOLUTION_RATIOS[state.aspect] ? state.aspect : aspectFor(state.width || 1024, state.height || 1024),
        megapixels: Math.max(0.1, Math.min(4, Math.round((Number(state.megapixels) || ((Number(state.width) || 1024) * (Number(state.height) || 1024) / (1024 * 1024))) * 10) / 10)),
        referenceResolution: snap32(state.referenceResolution),
        shots: shots.map((shot, index) => {
            const sourceImages = Array.isArray(shot.images) && shot.images.length ? shot.images : [null];
            const sourceImage = sourceImages.find((image) => String(image?.id || "") === String(shot.activeImageId || "")) || sourceImages[0];
            const images = [normalizeImage(sourceImage, 0, shot)];
            const activeImageId = images[0].id;
            return { id: String(shot.id || makeId()), title: String(shot.title || `分镜 ${index + 1}`), images, activeImageId };
        }),
        activeShotId: String(state.activeShotId || ""),
    };
    if (!state.shots.some((shot) => shot.id === state.activeShotId)) state.activeShotId = state.shots[0].id;
    return state;
};

