    root.insertAdjacentHTML("beforeend", `<div class="xmossaw-image-preview-backdrop" data-image-preview hidden><section class="xmossaw-image-preview-dialog"><header><b data-image-preview-title>分镜图片</b><nav><button type="button" data-preview-rename>改名字</button><button type="button" data-preview-add-asset>加入资产库</button><button type="button" class="danger" data-preview-delete>删除</button></nav><button type="button" data-image-preview-close>×</button></header><div class="xmossaw-image-preview-body"><button type="button" class="xmossaw-preview-arrow prev" data-preview-prev title="上一张" aria-label="上一张">‹</button><img data-image-preview-img alt="完整分镜图片"><button type="button" class="xmossaw-preview-arrow next" data-preview-next title="下一张" aria-label="下一张">›</button></div></section></div><div class="xmossaw-preview-asset-backdrop" data-preview-asset-dialog hidden><section class="xmossaw-preview-asset-dialog"><header><b>加入资产库</b><button type="button" data-preview-asset-close>×</button></header><label>资产分类<select data-preview-asset-category></select></label><div><input type="text" maxlength="60" placeholder="新建资产分类名称" data-preview-new-category><button type="button" data-preview-create-category>新建分类</button></div><small data-preview-asset-status>分类名称对应资产库文件夹</small><footer><button type="button" data-preview-asset-close>取消</button><button type="button" class="primary" data-preview-asset-confirm>加入资产库</button></footer></section></div>`);
    root.insertAdjacentHTML("beforeend", `<div class="xmossaw-dialog-backdrop" data-workbench-dialog hidden><section class="xmossaw-dialog"><header><b data-dialog-title>提示</b><button type="button" data-dialog-close>×</button></header><p data-dialog-message></p><textarea data-dialog-input hidden></textarea><footer><button type="button" data-dialog-cancel>取消</button><button type="button" class="primary" data-dialog-confirm>确定</button></footer></section></div>`);
    const q = (selector) => root.querySelector(selector);
