            q("[data-hw-cpu]").textContent = `CPU ${value.cpu ?? "--"}%`;
            q("[data-hw-memory]").textContent = `内存 ${value.memory ?? "--"}%`;
            q("[data-hw-vram]").textContent = `显存 ${value.vram ?? "--"}%`;
